#include <vector>
#include <unordered_map>
#include <unordered_set>

class Solution {
public:
    int minimumOperations(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::unordered_map<int, std::vector<int>> adj;
        std::vector<int> evenNodes;

        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1) {
                    int u = r * n + c;
                    if ((r + c) % 2 == 0) {
                        evenNodes.push_back(u);
                        for (auto& d : dirs) {
                            int nr = r + d[0], nc = c + d[1];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                                adj[u].push_back(nr * n + nc);
                            }
                        }
                    }
                }
            }
        }

        std::unordered_map<int, int> match;

        auto dfs = [&](auto& self, int u, std::unordered_set<int>& visited) -> bool {
            for (int v : adj[u]) {
                if (!visited.count(v)) {
                    visited.insert(v);
                    if (!match.count(v) || self(self, match[v], visited)) {
                        match[v] = u;
                        return true;
                    }
                }
            }
            return false;
        };

        int matching = 0;
        for (int u : evenNodes) {
            std::unordered_set<int> visited;
            if (dfs(dfs, u, visited)) matching++;
        }
        return matching;
    }
};

import java.util.*;

class Solution {
    public int minimumOperations(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Map<Integer, List<Integer>> adj = new HashMap<>();
        List<Integer> evenNodes = new ArrayList<>();

        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int u = r * n + c;
                    if ((r + c) % 2 == 0) {
                        evenNodes.add(u);
                        List<Integer> neighbors = new ArrayList<>();
                        for (int[] d : dirs) {
                            int nr = r + d[0], nc = c + d[1];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                                neighbors.add(nr * n + nc);
                            }
                        }
                        adj.put(u, neighbors);
                    }
                }
            }
        }

        Map<Integer, Integer> match = new HashMap<>();
        int matching = 0;

        for (int u : evenNodes) {
            Set<Integer> visited = new HashSet<>();
            if (dfs(u, adj, match, visited)) {
                matching++;
            }
        }
        return matching;
    }

    private boolean dfs(int u, Map<Integer, List<Integer>> adj, Map<Integer, Integer> match, Set<Integer> visited) {
        List<Integer> neighbors = adj.get(u);
        if (neighbors == null) return false;

        for (int v : neighbors) {
            if (!visited.contains(v)) {
                visited.add(v);
                if (!match.containsKey(v) || dfs(match.get(v), adj, match, visited)) {
                    match.put(v, u);
                    return true;
                }
            }
        }
        return false;
    }
}

