var minimumOperations = function(grid) {
    const m = grid.length, n = grid[0].length;
    const adj = new Map();
    const evenNodes = [];

    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                const u = r * n + c;
                if ((r + c) % 2 === 0) {
                    evenNodes.push(u);
                    const neighbors = [];
                    for (const [dr, dc] of dirs) {
                        const nr = r + dr, nc = c + dc;
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1) {
                            neighbors.push(nr * n + nc);
                        }
                    }
                    adj.set(u, neighbors);
                }
            }
        }
    }

    const match = new Map();

    const dfs = (u, visited) => {
        const neighbors = adj.get(u) || [];
        for (const v of neighbors) {
            if (!visited.has(v)) {
                visited.add(v);
                if (!match.has(v) || dfs(match.get(v), visited)) {
                    match.set(v, u);
                    return true;
                }
            }
        }
        return false;
    };

    let matching = 0;
    for (const u of evenNodes) {
        if (dfs(u, new Set())) matching++;
    }
    return matching;
};
